    int score = 0;
    int i = 0;                 // index of smallest token
    int j = tokens.length - 1; // index of largest token

    Arrays.sort(tokens);

    while (i <= j && (power >= tokens[i] || score > 0)) {
      while (i <= j && power >= tokens[i]) {
